import { useEffect, useRef } from 'react';

type Props = {
  svgList: {
    svg: SVGSVGElement;
    finishedMs: number;
  }[];
};

const Viewer = ({ svgList }: Props) => {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    svgList.forEach(({ svg }) => {
      if (ref.current) {
        ref.current.appendChild(svg);
      }
    });
    return () => {
      svgList.forEach(({ svg }) => {
        svg.remove();
      });
    };
  }, [svgList]);

  useEffect(() => {
    const hash = window.location.hash.slice(1);
    const searchParams = new URLSearchParams(hash);
    if (searchParams.get('autoplay') === 'no') {
      if (ref.current) {
        const ele = ref.current;
        const callback = () => {
          svgList.forEach(({ svg }) => {
            svg.setCurrentTime(0);
            svg.unpauseAnimations();
          });
        };
        ele.addEventListener('click', callback);
        return () => {
          ele.removeEventListener('click', callback);
        };
      }
    }
  }, [svgList]);

  const repeat = Math.ceil(Math.sqrt(svgList.length));
  const grids = `repeat(${repeat}, ${100 / repeat}%)`;

  return (
    <div
      className="Viewer-container"
      style={{
        height: '100vh',
        display: 'grid',
        gridTemplateColumns: grids,
        gridTemplateRows: grids,
      }}
      ref={ref}
    ></div>
  );
};

export default Viewer;

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';

import App from './App';
import './index.css';

